const babel = require("./packages/babel-core/lib/index.js");
const classes = require("./packages/babel-plugin-transform-classes/lib/index.js");
const objsuper = require("./packages/babel-plugin-transform-object-super/lib/index.js");

const classCode = `
let set;
let logged;
class B { set bar(v) { logged = v; } }
class C extends B {
  foo() {
    super.bar = 1;
  }
}
new C().foo();
if (logged !== 1) throw new Error("class super set failed");
`;
const objCode = `
let set;
let logged;
const o = {
  set bar(v) { logged = v; },
  foo() {
    super.bar = 1;
  }
};
o.foo();
if (logged !== 1) throw new Error("object super set failed");
`;

for (const [src, plugins] of [[classCode, classes], [objCode, objsuper]]) {
  new Function(
    babel.transform(src, { plugins, configFile: false, babelrc: false }).code
  )();
}
console.log("all ok");

